configExamples.code:
// NIST SP 800-63B §4.2: "AAL2 provides high confidence that the claimant
// controls authenticator(s) bound to the subscriber's account. Proof of
// possession and control of two different authentication factors is required."
{
  "name": "AAL2 MFA Policy Rule",
  "status": "ACTIVE",
  "conditions": {
    "network": { "connection": "ANYWHERE" }
  },
  "actions": {
    "signon": {
      "requireFactor": true,
      "factorPromptMode": "ALWAYS",
      "factorLifetime": 15,
      "access": "ALLOW",
      "primaryFactor": "PASSWORD_IDP_ANY_FACTOR"
    }
  }
}

// NIST SP 800-63B §4.3: "AAL3 authentication requires a hardware-based
// authenticator and an authenticator that provides verifier impersonation
// resistance." FIDO2/WebAuthn meets both requirements.
{
  "name": "AAL3 Phishing-Resistant Policy",
  "status": "ACTIVE",
  "conditions": {
    "network": { "connection": "ANYWHERE" }
  },
  "actions": {
    "signon": {
      "requireFactor": true,
      "factorPromptMode": "ALWAYS",
      "access": "ALLOW",
      "primaryFactor": "PASSWORD_IDP",
      "constraints": {
        "knowledge": { "required": true },
        "possession": {
          "required": true,
          "hardwareProtection": "REQUIRED",
          "phishingResistant": "REQUIRED"
        }
      }
    }
  }
}

// NIST SP 800-63B §7.1: "Session secrets SHALL be non-persistent."
// §7.2: "Session timeouts SHALL be limited based on the sensitivity of the data."
{
  "actions": {
    "signon": {
      "session": {
        "maxSessionIdleMinutes": 720,
        "maxSessionLifetimeMinutes": 1440,
        "usePersistentCookie": false
      }
    }
  }
}

{
  "type": "PASSWORD",
  "name": "CIS Compliant Password Policy",
  "settings": {
    "password": {
      "complexity": {
        "minLength": 14,
        "minLowerCase": 1,
        "minUpperCase": 1,
        "minNumber": 1,
        "minSymbol": 1,
        "excludeUsername": true,
        "dictionary": { "common": { "exclude": true } }
      },
      "age": {
        "maxAgeDays": 90,
        "historyCount": 24
      },
      "lockout": {
        "maxAttempts": 5,
        "autoUnlockMinutes": 30,
        "showLockoutFailures": true
      }
    }
  }
}

// GOOD: ThreatInsight enabled to detect and block credential-stuffing attacks
// Okta Best Practice: "ThreatInsight detects suspicious IP addresses and blocks them."
{
  "action": "AUDIT",           // Log suspicious activity
  "excludeZones": [],           // Apply to all zones
  "excludeIPs": []              // No IP exclusions
}

// BETTER: Block malicious IPs automatically
{
  "action": "BLOCK",            // Automatically block bad actors
  "excludeZones": [],
  "excludeIPs": []
}

// BAD: ThreatInsight disabled (default in some tenants)
{
  "action": "NONE"              // No protection - vulnerable to attacks
}

// GOOD: Bind admin sessions to ASN to prevent session hijacking
// Okta Best Practice: "ASN binding invalidates sessions if network changes."
{
  "type": "admin",
  "settings": {
    "session": {
      "bindToNetwork": true,    // Bind session to ASN
      "maxSessionLifetimeMinutes": 480
    }
  }
}

// BAD: No network binding - sessions can be hijacked
{
  "type": "admin",
  "settings": {
    "session": {
      "bindToNetwork": false,   // Session not bound to network
      "maxSessionLifetimeMinutes": 10080  // 7 days - too long
    }
  }
}

// GOOD: Enable behavior-based security rules
{
  "name": "Suspicious Location Policy",
  "type": "SIGN_ON",
  "conditions": {
    "riskScore": { "level": "HIGH" }
  },
  "actions": {
    "signon": {
      "requireFactor": true,
      "factorPromptMode": "ALWAYS",
      "session": { "maxSessionIdleMinutes": 15 }
    }
  }
}

// BAD: No behavior detection - ignores risk signals
{
  "name": "Weak Policy",
  "conditions": {},
  "actions": {
    "signon": {
      "requireFactor": false,
      "session": { "maxSessionIdleMinutes": 10080 }
    }
  }
}

// BAD: Password policy too weak for enterprise use
// Per NIST SP 800-63B §5.1.1.2: "Verifiers SHALL require passwords
// to be a minimum of 8 characters in length" (14+ recommended)
{
  "type": "PASSWORD",
  "settings": {
    "password": {
      "complexity": {
        "minLength": 8,              // TOO SHORT for enterprise
        "minLowerCase": 0,           // No lowercase requirement
        "minUpperCase": 0,           // No uppercase requirement
        "minNumber": 0,              // No number requirement
        "minSymbol": 0,              // No symbol requirement
        "excludeUsername": false,    // INSECURE - allows username in password
        "dictionary": { "common": { "exclude": false } }  // INSECURE
      },
      "lockout": {
        "maxAttempts": 100,          // TOO HIGH - enables brute force
        "autoUnlockMinutes": 1       // TOO SHORT - rapid retry
      }
    }
  }
}

// BAD: Only SMS/Voice MFA enrolled - vulnerable to SIM swapping
// Per NIST SP 800-63B §5.1.3.3: "Due to the risk that SMS messages
// may be intercepted or redirected, implementers of new systems SHOULD
// carefully consider alternative authenticators."
{
  "name": "Weak MFA Factor Enrollment",
  "settings": {
    "factors": {
      "okta_sms": { "enroll": "REQUIRED" },     // PHISHABLE
      "okta_call": { "enroll": "OPTIONAL" },    // PHISHABLE
      "okta_email": { "enroll": "OPTIONAL" },   // PHISHABLE
      "webauthn": { "enroll": "NOT_ALLOWED" },  // DISABLED - BAD!
      "okta_verify": { "enroll": "NOT_ALLOWED" }
    }
  }
}

// GOOD: Require phishing-resistant factors
// "webauthn": { "enroll": "REQUIRED" }
// "okta_verify": { "enroll": "REQUIRED", "deviceBound": true }

// BAD: Administrative accounts without enforced MFA
// Okta Best Practice: "All admin accounts should require MFA"
// Risk: Single compromised password grants full tenant access
{
  "type": "ACCESS_POLICY",
  "name": "Admin Access Policy",
  "rules": [{
    "name": "Admin Rule",
    "conditions": {
      "userType": { "include": ["Admin"] }
    },
    "actions": {
      "signon": {
        "access": "ALLOW",
        "requireFactor": false,      // CRITICAL RISK - no MFA!
        "primaryFactor": "PASSWORD_IDP"
      }
    }
  }]
}

// Risk: Scattered Spider and similar groups specifically target
// help desk and admin accounts without MFA enforcement

// CISA SCuBA GWS.COMMONCONTROLS.1.1v0.6:
// "Phishing-Resistant MFA SHALL be required for all users."
// MITRE ATT&CK: T1110 (Brute Force), T1566 (Phishing)
// NIST: IA-2(1), IA-2(2), IA-5c, IA-5g, IA-2(8)
{
  "2sv_enforcement": "ON",
  "2sv_methods": "ONLY_SECURITY_KEY",
  "security_codes": "DONT_ALLOW",
  "allow_user_trust_device": false,
  "new_user_enrollment_period": "1_WEEK"
}

// BAD: Default configuration allows weak MFA
{
  "2sv_enforcement": "OFF",
  "2sv_methods": "ANY",
  "allow_user_trust_device": true
}

// CISA SCuBA GWS.COMMONCONTROLS.1.3v0.6:
// "SMS or Voice as the MFA method SHALL NOT be used."
// MITRE ATT&CK: T1111 (Two-Factor Authentication Interception)
// NIST: CM-7b, IA-5c
{
  "2sv_methods": "ANY_EXCEPT_SMS_VOICE",
  "allowed_methods": [
    "security_key",
    "phone_as_security_key",
    "google_prompt",
    "google_authenticator"
  ],
  "blocked_methods": ["sms", "voice_call"]
}

// CISA SCuBA GWS.COMMONCONTROLS.2.1v0.6:
// "Policies restricting access based on signals about
// enterprise devices SHOULD be implemented."
// NIST: AC-3, AC-6

// GOOD: Require managed devices for sensitive apps
{
  "access_level": {
    "name": "Require Corporate Device",
    "conditions": [
      {
        "device_policy": {
          "require_corp_owned": true,
          "require_admin_approval": true,
          "require_screenlock": true,
          "require_encryption": true
        }
      }
    ]
  },
  "assigned_applications": [
    "Drive", "Gmail", "Calendar", "Admin Console"
  ]
}

// /etc/docker/daemon.json - CIS Docker Benchmark recommended settings
{
  "icc": false,                           // CIS 2.1: Disable inter-container communication
  "userns-remap": "default",              // CIS 2.8: Enable user namespace remapping
  "no-new-privileges": true,              // CIS 2.17: Prevent privilege escalation
  "live-restore": true,                   // CIS 2.14: Keep containers on daemon downtime
  "userland-proxy": false,                // CIS 2.15: Use iptables directly
  "log-driver": "json-file",              // CIS 2.12: Configure logging
  "log-opts": {
    "max-size": "10m",
    "max-file": "3"
  },
  "storage-driver": "overlay2",           // CIS 2.5: Use secure storage driver
  "default-ulimits": {
    "nofile": { "Hard": 64000, "Soft": 64000 }
  }
}

// BAD: Insecure Docker daemon settings - DO NOT USE
{
  "icc": true,                           // BAD: Allows container-to-container attacks
  "userns-remap": "",                    // BAD: No user namespace isolation
  "iptables": false,                     // BAD: Disables network isolation
  "tls": false,                          // BAD: No TLS for remote API
  "hosts": ["tcp://0.0.0.0:2375"]        // CRITICAL: Unauthenticated remote access
}
// WARNING: tcp://0.0.0.0:2375 exposes Docker API without authentication
// This is a common attack vector for cryptomining malware

// Custom seccomp profile restricting syscalls
// CIS 5.21: "Apply a seccomp profile to containers"
{
  "defaultAction": "SCMP_ACT_ERRNO",
  "architectures": ["SCMP_ARCH_X86_64"],
  "syscalls": [
    {
      "names": ["read", "write", "open", "close", "stat", "fstat",
                "lstat", "poll", "lseek", "mmap", "mprotect", "munmap",
                "brk", "rt_sigaction", "rt_sigprocmask", "ioctl", "access",
                "pipe", "select", "sched_yield", "dup", "dup2", "nanosleep",
                "getpid", "socket", "connect", "accept", "sendto", "recvfrom",
                "bind", "listen", "getsockname", "getpeername", "socketpair",
                "clone", "fork", "vfork", "execve", "exit", "wait4", "kill",
                "getcwd", "chdir", "rename", "mkdir", "rmdir", "link", "unlink"],
      "action": "SCMP_ACT_ALLOW"
    }
  ]
}
// Usage: docker run --security-opt seccomp=profile.json myapp

# NIST SP 800-204 MS-SS-4: "Service to Service communication should
# take place after mutual authentication and be encrypted."
Kind = "service-intentions"
Name = "backend"
Sources = [
  {
    Name   = "frontend"
    Action = "allow"
  },
  {
    Name   = "*"
    Action = "deny"  # Default deny all other services
  }
]

# NIST SP 800-204A SM-DR8: "All traffic should be denied by default
# and explicitly allowed to required services (allowlisting)."
acl = {
  enabled        = true
  default_policy = "deny"
  down_policy    = "extend-cache"

  tokens = {
    agent   = "agent-token-here"
    default = "default-token-here"
  }
}

# NIST SP 800-204A SM-DR1: "All service-to-service communications
# within the cluster should be authenticated."
# SM-DR6: "All traffic should be encrypted using mutual TLS."
tls = {
  defaults = {
    verify_incoming = true
    verify_outgoing = true
    ca_file         = "/etc/consul.d/ca.pem"
    cert_file       = "/etc/consul.d/server.pem"
    key_file        = "/etc/consul.d/server-key.pem"
  }

  internal_rpc = {
    verify_server_hostname = true
  }
}

Kind = "service-intentions"
Name = "*"
Sources = [
  {
    Name   = "*"
    Action = "deny"
  }
]

Kind = "service-intentions"
Name = "backend"
Sources = [
  {
    Name   = "frontend"
    Action = "allow"
  },
  {
    Name   = "monitoring"
    Action = "allow"
    Permissions = [
      {
        Action = "allow"
        HTTP {
          PathPrefix = "/health"
          Methods    = ["GET"]
        }
      }
    ]
  }
]

service {
  name = "api"
  port = 8080

  connect {
    sidecar_service {
      proxy {
        local_service_address = "127.0.0.1"

        config {
          protocol = "http"
        }

        upstreams = [
          {
            destination_name = "database"
            local_bind_port  = 5432
          }
        ]
      }
    }
  }
}

// NIST SP 800-83 §3.4.1: "Antivirus software should be configured
// to perform real-time scans of each file as it is downloaded,
// opened, or executed, which is known as on-access scanning."
{
  "name": "High-Security Prevention Policy",
  "platform_name": "Windows",
  "settings": {
    "prevention": {
      "cloud_anti_malware": { "enabled": true },
      "sensor_anti_malware": { "enabled": true },
      "script_based_execution_monitoring": { "enabled": true },
      "memory_scanning": { "enabled": true },
      "next_gen_av": { "enabled": true },
      "quarantine": { "enabled": true }
    }
  }
}

// NIST SP 800-83 §3.4.1: "Antivirus software should be configured
// to attempt to disinfect infected files and to either quarantine
// or delete files that cannot be disinfected."
{
  "name": "Quarantine Policy",
  "detection_actions": {
    "on_detection": "quarantine",
    "on_quarantine_failure": "prevent_execution",
    "retention_days": 30,
    "notify_user": true,
    "notify_admin": true
  }
}

{
  "name": "Auto-Update Policy",
  "platform_name": "Windows",
  "settings": {
    "sensor_update": {
      "uninstall_protection": "ENABLED",
      "build": "N-1"
    },
    "scheduler": {
      "enabled": true,
      "timezone": "UTC"
    }
  }
}

// BAD: Prevention disabled - only detects, doesn't block threats
// Per NIST SP 800-83 §3.4.1: "Antivirus software should be configured
// to attempt to disinfect infected files and to either quarantine
// or delete files that cannot be disinfected."
{
  "name": "Weak Prevention Policy",
  "platform_name": "Windows",
  "settings": {
    "prevention": {
      "cloud_anti_malware": { "detection": "DETECT" },   // NOT BLOCKING
      "sensor_anti_malware": { "detection": "DETECT" },  // NOT BLOCKING
      "next_gen_av": { "enabled": false },               // DISABLED!
      "script_based_execution_monitoring": { "enabled": false },
      "quarantine": { "enabled": false }                 // NO QUARANTINE
    }
  }
}

// Risk: Malware executes freely, only generating alerts
// After July 2024 CrowdStrike incident, review prevention settings

// BAD: Uninstall protection disabled - attackers can remove sensor
// Common attack pattern: Disable EDR before deploying ransomware
{
  "name": "Unprotected Sensor Policy",
  "platform_name": "Windows",
  "settings": {
    "sensor_update": {
      "uninstall_protection": "DISABLED",  // CRITICAL - can be removed!
      "maintenance_token": null            // No protection token set
    }
  }
}

// Risk: Threat actors use:
// - CSUninstall.exe with no token required
// - Safe mode boot to bypass sensor
// - Vulnerable driver loading (BYOVD) attacks

// BAD: Broad exclusions create detection blind spots
// Common misconfiguration that enables attacker evasion
{
  "name": "Overly Permissive Exclusions",
  "exclusions": [
    { "path": "C:\\*", "type": "path" },           // TOO BROAD!
    { "path": "*.exe", "type": "extension" },       // EXCLUDES ALL EXEs!
    { "process": "powershell.exe", "type": "process" },  // ABUSED BY ATTACKERS
    { "path": "C:\\Windows\\Temp\\*" }        // COMMON STAGING AREA
  ]
}

// GOOD: Minimal, specific exclusions with business justification
{
  "name": "Minimal Required Exclusions",
  "exclusions": [
    { "path": "C:\\SpecificApp\\verified.exe", "type": "path" }
  ]
}

// BAD: RTR disabled prevents rapid incident containment
// Per NIST SP 800-61r2 §3.3.1: "Containment provides time for
// developing a tailored remediation strategy."
{
  "name": "Limited Response Policy",
  "response_policies": {
    "real_time_response": {
      "enabled": false,                    // DISABLED - no remote access
      "run_script": false,
      "put_files": false,
      "get_files": false
    },
    "network_containment": {
      "enabled": false                     // CANNOT ISOLATE HOSTS
    }
  }
}

// Risk: When breach occurs, IR team cannot:
// - Collect forensic evidence remotely
// - Isolate infected hosts from network
// - Deploy remediation scripts

// NIST SP 800-61r2 §3.2.6: "Prioritizing the handling of the incident
// is perhaps the most critical decision point in the incident handling process."
{
  "detection_priority_rules": {
    "critical": {
      "severity": ["Critical", "High"],
      "tactics": ["Execution", "Credential Access", "Lateral Movement"],
      "action": "immediate_alert"
    },
    "high": {
      "severity": ["High", "Medium"],
      "tactics": ["Defense Evasion", "Persistence"],
      "action": "alert_within_15min"
    }
  }
}

// NIST SP 800-86 §5.1.2: "Volatile data is data that would be lost
// if the computer were powered down...includes information on running
// processes, open network connections, and contents of memory."
{
  "investigation_query": {
    "type": "process_tree",
    "host_id": "HOST_AID",
    "include": [
      "process_name",
      "parent_process",
      "command_line",
      "network_connections",
      "loaded_modules",
      "file_writes"
    ],
    "time_range": "last_24h"
  }
}

{
  "BlockPublicAcls": true,
  "IgnorePublicAcls": true,
  "BlockPublicPolicy": true,
  "RestrictPublicBuckets": true
}

{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "AllowSSLRequestsOnly",
    "Effect": "Deny",
    "Principal": "*",
    "Action": "s3:*",
    "Resource": [
      "arn:aws:s3:::BUCKET-NAME",
      "arn:aws:s3:::BUCKET-NAME/*"
    ],
    "Condition": {
      "Bool": { "aws:SecureTransport": "false" }
    }
  }]
}

// BAD: Public bucket with wildcard principal - data breach risk
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "PublicReadAccess",
    "Effect": "Allow",
    "Principal": "*",                 // BAD: Anyone on internet
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::my-bucket/*"
  }]
}

// WORSE: Public write access - allows attackers to modify data
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": "*",
    "Action": ["s3:GetObject", "s3:PutObject"],  // BAD: Write access!
    "Resource": "arn:aws:s3:::my-bucket/*"
  }]
}

// NIST SP 800-145 IaaS: "The consumer has control over operating systems,
// storage, and deployed applications; and possibly limited control of
// select networking components (e.g., host firewalls)."
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": [
      "s3:GetObject",
      "s3:ListBucket"
    ],
    "Resource": [
      "arn:aws:s3:::my-bucket",
      "arn:aws:s3:::my-bucket/*"
    ]
  }]
}

# NIST SP 800-57 §5.3.6: "Keys should have a limited
# cryptoperiod to limit the amount of data protected by a single key."
resource "aws_kms_key" "main" {
  description             = "Encryption key with automatic rotation"
  deletion_window_in_days = 30
  enable_key_rotation     = true  # Rotates annually per NIST guidance

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "Enable IAM policies"
      Effect    = "Allow"
      Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
      Action    = "kms:*"
      Resource  = "*"
    }]
  })
}

# NIST SP 800-144 §4.7: "Organizations should employ appropriate
# safeguards to protect data in transit and at rest."
resource "aws_s3_bucket_server_side_encryption_configuration" "example" {
  bucket = aws_s3_bucket.example.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.example.arn
    }
    bucket_key_enabled = true
  }
}

// BAD: IAM user with static access keys - security risk
// AWS Best Practice: "Require workloads to use temporary credentials
// with IAM roles to access AWS"
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": "*",                    // BAD: Overly permissive
    "Resource": "*"
  }]
}
// Anti-pattern: Creating IAM users with console access keys

// GOOD: Use IAM Roles with temporary credentials
// "IAM roles provide temporary credentials for cross-account access"

// AWS Best Practice: "Grant only the permissions required to
// perform a task (least-privilege permissions)"
{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "ReadSpecificBucket",
    "Effect": "Allow",
    "Action": [
      "s3:GetObject",
      "s3:ListBucket"
    ],
    "Resource": [
      "arn:aws:s3:::my-app-data",
      "arn:aws:s3:::my-app-data/*"
    ],
    "Condition": {
      "StringEquals": {
        "aws:PrincipalTag/team": "data-science"
      }
    }
  }]
}

// AWS Best Practice: "Establish permissions guardrails
// across multiple accounts with SCPs"
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyRootUserActions",
      "Effect": "Deny",
      "Action": "*",
      "Resource": "*",
      "Condition": {
        "StringLike": {
          "aws:PrincipalArn": "arn:aws:iam::*:root"
        }
      }
    },
    {
      "Sid": "RequireIMDSv2",
      "Effect": "Deny",
      "Action": "ec2:RunInstances",
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringNotEquals": {
          "ec2:MetadataHttpTokens": "required"
        }
      }
    }
  ]
}

// BAD: Wildcard actions + wildcard resources = admin access
// AWS Best Practice: "Apply least-privilege permissions... grant only
// the permissions required to perform a task."
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": "ec2:*",              // BAD: ALL EC2 actions
    "Resource": "*"                 // BAD: ALL resources
    // Missing: Conditions to restrict scope
  }]
}

// Common anti-patterns:
// - "Action": "*"                  -> Full admin access
// - "Action": "s3:*"               -> Can delete any bucket
// - "Action": "iam:*"              -> Can create backdoor accounts
// - "Resource": "*"                -> Affects all resources in account

// Per AWS: "Grant only permissions required to perform a task"

// BAD: Allows destructive actions without MFA
// AWS Best Practice: "Require multi-factor authentication (MFA)"
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": [
      "iam:CreateUser",
      "iam:DeleteUser",
      "iam:AttachUserPolicy",
      "ec2:TerminateInstances",
      "s3:DeleteBucket",
      "rds:DeleteDBInstance"
    ],
    "Resource": "*"
    // MISSING: MFA condition - attackers with stolen creds
    // can perform destructive actions!
  }]
}

// GOOD: Require MFA for sensitive operations
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Action": ["iam:*", "ec2:Terminate*", "s3:Delete*"],
    "Resource": "*",
    "Condition": {
      "Bool": { "aws:MultiFactorAuthPresent": "true" }
    }
  }]
}

// BAD: Role trust policy vulnerable to confused deputy attack
// Per AWS: "Use an external ID with third parties"
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": {
      "AWS": "arn:aws:iam::VENDOR-ACCOUNT:root"
    },
    "Action": "sts:AssumeRole"
    // MISSING: External ID condition!
    // Any customer of the vendor could assume this role
  }]
}

// GOOD: Require External ID to prevent confused deputy
