        "What happened and when?",
        "How well did staff perform?",
        "What could staff do differently?",
        "What additional resources are needed?"
      ]
    },
    {
      "type": "change_request",
      "template": "security_improvement",
      "auto_create": true
    }
  ]
}

// Deny wildcard Bedrock access; allow InvokeModel only on a specific model.
// Replace REGION, ACCOUNT_ID, and the model identifier as needed.
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyWildcardBedrock",
      "Effect": "Deny",
      "Action": "bedrock:*",
      "Resource": "*"
    },
    {
      "Sid": "AllowSpecificModelInvocation",
      "Effect": "Allow",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": "arn:aws:bedrock:REGION:ACCOUNT_ID:foundation-model/anthropic.claude-3-5-sonnet-20241022-v2:0"
    }
  ]
}

// Organization SCP: block InvokeModel except for approved model IDs.
// Attach to the OU containing Bedrock workload accounts.
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyUnapprovedModels",
      "Effect": "Deny",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": "*",
      "Condition": {
        "ForAnyValue:StringNotLike": {
          "bedrock:FoundationModelIdentifier": [
            "anthropic.claude-3-5-sonnet-*",
            "anthropic.claude-3-haiku-*"
          ]
        }
      }
    }
  ]
}

// Only allow inference via a provisioned throughput, not on-demand.
// This ensures cost control and reserved capacity usage.
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowProvisionedModelOnly",
      "Effect": "Allow",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": "arn:aws:bedrock:us-east-1:123456789012:provisioned-model/*"
    },
    {
      "Sid": "DenyOnDemandInference",
      "Effect": "Deny",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": "arn:aws:bedrock:*::foundation-model/*"
    }
  ]
}

# Enable model invocation logging with both CloudWatch Logs and S3 destinations.
# Prerequisites: CloudWatch log group and S3 bucket must exist with proper policies.

aws bedrock put-model-invocation-logging-configuration \
  --logging-config '{
    "cloudWatchConfig": {
      "logGroupName": "/aws/bedrock/model-invocations",
      "roleArn": "arn:aws:iam::123456789012:role/BedrockLoggingRole",
      "largeDataDeliveryS3Config": {
        "bucketName": "my-bedrock-logs",
        "keyPrefix": "large-data/"
      }
    },
    "s3Config": {
      "bucketName": "my-bedrock-logs",
      "keyPrefix": "invocations/"
    },
    "textDataDeliveryEnabled": true,
    "imageDataDeliveryEnabled": true,
    "embeddingDataDeliveryEnabled": true
  }'

# Create a guardrail with content filters (block HATE/VIOLENCE at HIGH)
# and PII detection (anonymize SSN, email, phone).

aws bedrock create-guardrail \
  --name "production-safety-guardrail" \
  --description "Content safety and PII protection for production workloads" \
  --blocked-input-messaging "Your request was blocked by our safety policy." \
  --blocked-outputs-messaging "The model response was blocked by our safety policy." \
  --content-policy-config '{
    "filtersConfig": [
      { "type": "HATE",       "inputStrength": "HIGH", "outputStrength": "HIGH" },
      { "type": "INSULTS",    "inputStrength": "HIGH", "outputStrength": "HIGH" },
      { "type": "SEXUAL",     "inputStrength": "HIGH", "outputStrength": "HIGH" },
      { "type": "VIOLENCE",   "inputStrength": "HIGH", "outputStrength": "HIGH" },
      { "type": "MISCONDUCT", "inputStrength": "HIGH", "outputStrength": "HIGH" },
      { "type": "PROMPT_ATTACK", "inputStrength": "HIGH", "outputStrength": "NONE" }
    ]
  }' \
  --sensitive-information-policy-config '{
    "piiEntitiesConfig": [
      { "type": "US_SOCIAL_SECURITY_NUMBER", "action": "ANONYMIZE" },
      { "type": "EMAIL",                     "action": "ANONYMIZE" },
      { "type": "PHONE",                     "action": "ANONYMIZE" },
      { "type": "CREDIT_DEBIT_CARD_NUMBER",  "action": "BLOCK" }
    ]
  }'

// Organization SCP: deny InvokeModel unless a guardrailIdentifier is present.
// This forces all Bedrock inference calls to go through a guardrail.
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "RequireGuardrailOnInvoke",
      "Effect": "Deny",
      "Action": [
        "bedrock:InvokeModel",
        "bedrock:InvokeModelWithResponseStream"
      ],
      "Resource": "*",
      "Condition": {
        "StringNotLike": {
          "bedrock:GuardrailIdentifier": "arn:aws:bedrock:*:*:guardrail/*"
        }
      }
    }
  ]
}
